-- Document every seeded table and column. Keeping this data-driven ensures new
-- seed columns cannot silently be left undocumented.
DECLARE
  FUNCTION words(identifier VARCHAR2) RETURN VARCHAR2 IS
  BEGIN
    RETURN REPLACE(LOWER(identifier), '_', ' ');
  END;

  FUNCTION quoted_literal(value VARCHAR2) RETURN VARCHAR2 IS
  BEGIN
    RETURN '''' || REPLACE(value, '''', '''''') || '''';
  END;

  FUNCTION schema_purpose(owner_name VARCHAR2) RETURN VARCHAR2 IS
  BEGIN
    RETURN CASE owner_name
      WHEN 'IAM' THEN 'identity and access management'
      WHEN 'CATALOG' THEN 'product catalog and inventory management'
      WHEN 'COMMERCE' THEN 'ordering and fulfillment'
      WHEN 'FINANCE' THEN 'accounting and payment processing'
    END;
  END;

  FUNCTION table_description(owner_name VARCHAR2, table_name VARCHAR2) RETURN VARCHAR2 IS
  BEGIN
    RETURN 'Stores ' || words(table_name) || ' used for the seeded ' ||
      schema_purpose(owner_name) || ' example.';
  END;

  FUNCTION column_description(table_name VARCHAR2, column_name VARCHAR2) RETURN VARCHAR2 IS
    label VARCHAR2(200) := words(column_name);
  BEGIN
    RETURN CASE
      WHEN column_name IN ('BEFORE_STATE', 'AFTER_STATE', 'CHANGE_DOCUMENT', 'PAYLOAD',
                           'POLICY_DOCUMENT', 'PROFILE_JSON', 'RULE_DOCUMENT') OR
           (table_name = 'FINANCE_AUDIT' AND column_name = 'DETAILS')
        THEN 'JSON document containing the ' || label || '.'
      WHEN column_name LIKE '%\_ID' ESCAPE '\'
        THEN 'Identifier for the ' || REPLACE(label, ' id', '') || ' associated with this record.'
      WHEN column_name LIKE '%\_AT' ESCAPE '\'
        THEN 'Date and time when the ' || REPLACE(label, ' at', '') || ' event occurred.'
      WHEN column_name LIKE '%\_ON' ESCAPE '\'
        THEN 'Calendar date for the ' || REPLACE(label, ' on', '') || ' event.'
      WHEN column_name LIKE '%\_CODE' ESCAPE '\'
        THEN 'Business code identifying the ' || REPLACE(label, ' code', '') || '.'
      WHEN column_name LIKE '%\_NAME' ESCAPE '\'
        THEN 'Human-readable name of the ' || REPLACE(label, ' name', '') || '.'
      WHEN column_name LIKE '%\_NUMBER' ESCAPE '\'
        THEN 'Business-facing number identifying the ' || REPLACE(label, ' number', '') || '.'
      WHEN column_name LIKE '%\_REFERENCE' ESCAPE '\' OR column_name = 'EXTERNAL_ID'
        THEN 'External or business reference used to correlate this ' || words(table_name) || ' record.'
      WHEN column_name LIKE '%\_AMOUNT' ESCAPE '\' OR column_name IN
           ('SUBTOTAL', 'TAX_TOTAL', 'GRAND_TOTAL', 'UNIT_COST', 'UNIT_PRICE', 'LINE_TOTAL')
        THEN 'Monetary value represented by ' || label || ', in the record currency.'
      WHEN column_name LIKE '%QUANTITY%' OR column_name LIKE '%\_QTY' ESCAPE '\' OR
           column_name IN ('ON_HAND', 'RESERVED', 'AVAILABLE')
        THEN 'Quantity represented by ' || label || ' in the applicable unit of measure.'
      WHEN column_name IN ('ACTIVE', 'ENABLED', 'IS_DEFAULT', 'IS_PRIMARY', 'LOT_CONTROLLED',
                           'RECONCILED', 'SERIAL_CONTROLLED', 'SUCCEEDED')
        THEN 'Boolean flag indicating whether ' || label || ' is true.'
      WHEN column_name IN ('STATUS', 'TASK_STATUS', 'LIFECYCLE_STATUS')
        THEN 'Current lifecycle status of this ' || words(table_name) || ' record.'
      WHEN column_name IN ('DESCRIPTION', 'DETAILS', 'MEMO', 'NOTE', 'NOTE_TEXT', 'PURPOSE',
                           'REASON', 'REVIEW_TEXT')
        THEN 'Descriptive text providing ' || label || ' for this record.'
      WHEN column_name IN ('CURRENCY_CODE', 'COUNTRY_CODE', 'LOCALE_CODE', 'UOM_CODE')
        THEN 'Standard code specifying the ' || REPLACE(label, ' code', '') || '.'
      WHEN column_name = 'LINE_NO'
        THEN 'Sequence number uniquely locating this line within its parent record.'
      WHEN column_name IN ('VALID_FROM', 'STARTS_AT', 'STARTS_ON', 'ISSUED_AT')
        THEN 'Date or timestamp when this record becomes effective.'
      WHEN column_name IN ('VALID_TO', 'VALID_UNTIL', 'ENDS_AT', 'ENDS_ON', 'EXPIRES_AT', 'EXPIRES_ON')
        THEN 'Date or timestamp after which this record is no longer effective.'
      WHEN column_name LIKE '%\_TYPE' ESCAPE '\' OR column_name IN ('ACTION_NAME', 'CHANNEL',
           'DISPOSITION', 'EFFECT', 'OPERATION', 'VISIBILITY')
        THEN 'Classification value describing the ' || label || '.'
      WHEN column_name LIKE '%\_URL%' ESCAPE '\'
        THEN 'URL used for ' || label || '.'
      WHEN column_name LIKE '%\_HASH' ESCAPE '\' OR column_name IN
           ('ACCOUNT_FINGERPRINT', 'PUBLIC_KEY', 'SECRET_HASH', 'TOKEN_REFERENCE')
        THEN 'Non-plaintext security value used for ' || label || '.'
      ELSE 'Value of ' || label || ' for this ' || words(table_name) || ' record.'
    END;
  END;
BEGIN
  FOR table_record IN (
    SELECT owner, table_name
      FROM all_tables
     WHERE owner IN ('IAM', 'CATALOG', 'COMMERCE', 'FINANCE')
     ORDER BY owner, table_name
  ) LOOP
    EXECUTE IMMEDIATE
      'COMMENT ON TABLE ' || DBMS_ASSERT.ENQUOTE_NAME(table_record.owner) || '.' ||
      DBMS_ASSERT.ENQUOTE_NAME(table_record.table_name) || ' IS ' ||
      quoted_literal(table_description(table_record.owner, table_record.table_name));

    FOR column_record IN (
      SELECT column_name
        FROM all_tab_columns
       WHERE owner = table_record.owner
         AND table_name = table_record.table_name
       ORDER BY column_id
    ) LOOP
      EXECUTE IMMEDIATE
        'COMMENT ON COLUMN ' || DBMS_ASSERT.ENQUOTE_NAME(table_record.owner) || '.' ||
        DBMS_ASSERT.ENQUOTE_NAME(table_record.table_name) || '.' ||
        DBMS_ASSERT.ENQUOTE_NAME(column_record.column_name) || ' IS ' ||
        quoted_literal(column_description(table_record.table_name, column_record.column_name));
    END LOOP;
  END LOOP;
END;
/

BEGIN
  EXECUTE IMMEDIATE 'COMMENT ON TABLE IAM.PRINCIPALS IS ''Users'''' directory & lifecycle ' || UNISTR(CHR(92) || '2014') || ' exact text''';
  EXECUTE IMMEDIATE 'COMMENT ON COLUMN IAM.PRINCIPALS.EMAIL IS ''Primary address' || CHR(10) || 'Unicode ' || UNISTR(CHR(92) || '03A9') || ' & apostrophe''''s test''';
  EXECUTE IMMEDIATE 'COMMENT ON COLUMN CATALOG.PRODUCTS.PRODUCT_NAME IS ''' || RPAD('L', 3900, 'L') || '''';
END;
/

-- Conventional views: chains, a diamond, joins, aliases, quoted names, cross-schema edges, and restrictions.
ALTER SESSION SET CURRENT_SCHEMA = CATALOG;
CREATE VIEW active_products (product_id, sku, product_name, lifecycle_status) AS
  SELECT product_id, sku, product_name, lifecycle_status FROM products WHERE lifecycle_status = 'ACTIVE'
  WITH CHECK OPTION CONSTRAINT cat_active_products_ck;
CREATE VIEW "Product Availability" (product_id, sku, product_name, available_quantity) BEQUEATH CURRENT_USER AS
  SELECT p.product_id, p.sku, p.product_name, NVL(SUM(s.available), 0)
    FROM active_products p LEFT JOIN product_variants v ON v.product_id = p.product_id
    LEFT JOIN inventory_items i ON i.variant_id = v.variant_id
    LEFT JOIN stock_levels s ON s.item_id = i.item_id
   GROUP BY p.product_id, p.sku, p.product_name
  WITH READ ONLY;

GRANT SELECT ON CATALOG.active_products TO COMMERCE;
GRANT SELECT ON CATALOG.product_variants TO COMMERCE;
ALTER SESSION SET CURRENT_SCHEMA = COMMERCE;
CREATE VIEW open_orders (order_id, customer_id, order_number, status, grand_total) BEQUEATH CURRENT_USER AS
  SELECT order_id, customer_id, order_number, status, grand_total FROM sales_orders WHERE status IN ('PENDING', 'PAID')
  WITH CHECK OPTION CONSTRAINT com_open_orders_ck;
CREATE VIEW order_product_rollup (order_id, order_number, line_count, merchandise_total) AS
  SELECT o.order_id, o.order_number, COUNT(l.line_no), NVL(SUM(l.line_total), 0)
    FROM open_orders o LEFT JOIN order_lines l ON l.order_id = o.order_id
   GROUP BY o.order_id, o.order_number
  WITH READ ONLY;

GRANT SELECT ON COMMERCE.open_orders TO FINANCE;
GRANT SELECT ON COMMERCE.order_product_rollup TO FINANCE;
ALTER SESSION SET CURRENT_SCHEMA = FINANCE;
CREATE VIEW open_order_finance (order_id, order_number, line_count, merchandise_total, invoice_id, invoice_status) AS
  SELECT o.order_id, o.order_number, r.line_count, r.merchandise_total, i.invoice_id, i.status
    FROM COMMERCE.open_orders o
    JOIN COMMERCE.order_product_rollup r ON r.order_id = o.order_id
    LEFT JOIN invoices i ON i.order_id = o.order_id
  WITH READ ONLY;

-- Packages mix direct local-table references with private cross-schema synonyms.
-- Synonyms do not confer privileges: package owners need direct object grants.
GRANT SELECT ON COMMERCE.order_lines TO CATALOG;
ALTER SESSION SET CURRENT_SCHEMA = COMMERCE;
CREATE SYNONYM catalog_variants FOR CATALOG.product_variants;

CREATE PACKAGE order_management AUTHID DEFINER AS
  FUNCTION order_total(p_order_id NUMBER) RETURN NUMBER;
  FUNCTION variant_sku(p_variant_id NUMBER) RETURN VARCHAR2;
  PROCEDURE refresh_subtotal(p_order_id NUMBER);
  PROCEDURE set_order_status(p_order_id NUMBER, p_status VARCHAR2);
END order_management;
/

CREATE PACKAGE BODY order_management AS
  FUNCTION order_total(p_order_id NUMBER) RETURN NUMBER IS
    v_total NUMBER;
  BEGIN
    SELECT NVL(SUM(line_total), 0) INTO v_total
      FROM order_lines WHERE order_id = p_order_id;
    RETURN v_total;
  END order_total;

  FUNCTION variant_sku(p_variant_id NUMBER) RETURN VARCHAR2 IS
    v_sku catalog_variants.variant_sku%TYPE;
  BEGIN
    SELECT variant_sku INTO v_sku
      FROM catalog_variants WHERE variant_id = p_variant_id;
    RETURN v_sku;
  END variant_sku;

  PROCEDURE refresh_subtotal(p_order_id NUMBER) IS
  BEGIN
    UPDATE sales_orders SET subtotal = order_total(p_order_id)
      WHERE order_id = p_order_id;
    IF SQL%ROWCOUNT = 0 THEN
      RAISE NO_DATA_FOUND;
    END IF;
  END refresh_subtotal;

  PROCEDURE set_order_status(p_order_id NUMBER, p_status VARCHAR2) IS
    v_old_status sales_orders.status%TYPE;
  BEGIN
    IF p_status IS NULL THEN
      RAISE_APPLICATION_ERROR(-20001, 'Order status must not be null.');
    END IF;
    SELECT status INTO v_old_status
      FROM sales_orders WHERE order_id = p_order_id FOR UPDATE;
    -- Insert first so a rejected history row cannot leave an unrecorded update.
    INSERT INTO order_status_history (order_id, old_status, new_status)
      VALUES (p_order_id, v_old_status, p_status);
    UPDATE sales_orders SET status = p_status WHERE order_id = p_order_id;
  END set_order_status;
END order_management;
/

ALTER SESSION SET CURRENT_SCHEMA = CATALOG;
CREATE SYNONYM commerce_order_lines FOR COMMERCE.order_lines;

CREATE PACKAGE inventory_management AUTHID DEFINER AS
  FUNCTION available_quantity(p_warehouse_id NUMBER, p_item_id NUMBER) RETURN NUMBER;
  FUNCTION ordered_quantity(p_variant_id NUMBER) RETURN NUMBER;
  PROCEDURE reserve_stock(p_warehouse_id NUMBER, p_item_id NUMBER, p_quantity NUMBER);
  PROCEDURE set_product_status(p_product_id NUMBER, p_status VARCHAR2);
END inventory_management;
/

CREATE PACKAGE BODY inventory_management AS
  FUNCTION available_quantity(p_warehouse_id NUMBER, p_item_id NUMBER) RETURN NUMBER IS
    v_available NUMBER;
  BEGIN
    SELECT available INTO v_available FROM stock_levels
      WHERE warehouse_id = p_warehouse_id AND item_id = p_item_id;
    RETURN v_available;
  END available_quantity;

  FUNCTION ordered_quantity(p_variant_id NUMBER) RETURN NUMBER IS
    v_quantity NUMBER;
  BEGIN
    SELECT NVL(SUM(quantity), 0) INTO v_quantity
      FROM commerce_order_lines WHERE variant_id = p_variant_id;
    RETURN v_quantity;
  END ordered_quantity;

  PROCEDURE reserve_stock(p_warehouse_id NUMBER, p_item_id NUMBER, p_quantity NUMBER) IS
  BEGIN
    IF p_quantity IS NULL OR p_quantity <= 0 THEN
      RAISE_APPLICATION_ERROR(-20002, 'Reservation quantity must be positive.');
    END IF;
    UPDATE stock_levels SET reserved = reserved + p_quantity
      WHERE warehouse_id = p_warehouse_id AND item_id = p_item_id
        AND available >= p_quantity;
    IF SQL%ROWCOUNT = 0 THEN
      RAISE_APPLICATION_ERROR(-20003, 'Stock row missing or insufficient available quantity.');
    END IF;
  END reserve_stock;

  PROCEDURE set_product_status(p_product_id NUMBER, p_status VARCHAR2) IS
  BEGIN
    UPDATE products SET lifecycle_status = p_status WHERE product_id = p_product_id;
    IF SQL%ROWCOUNT = 0 THEN
      RAISE NO_DATA_FOUND;
    END IF;
  END set_product_status;
END inventory_management;
/

-- Boundary values are part of the ordinary reconstruction, without adding tables.
ALTER TABLE IAM.permissions ADD (
  literal_probe VARCHAR2(80 CHAR) DEFAULT 'it''s  (exact)',
  rounded_probe NUMBER(8,-2) DEFAULT 12345,
  byte_probe VARCHAR2(17 BYTE),
  char_probe VARCHAR2(17 CHAR)
);

-- Integration-test accounts for this disposable example database only.
-- Real extraction uses an existing supplied account; it never runs this seed,
-- creates these users, requires proxy authentication, or changes source grants.
-- Passwordless proxy targets: authentication uses the existing SYSTEM secret,
-- but catalog visibility and privileges belong to the restricted session user.
CREATE USER SCHEMA_READER NO AUTHENTICATION;
CREATE USER LIMITED_READER NO AUTHENTICATION;
GRANT CREATE SESSION TO SCHEMA_READER, LIMITED_READER;
ALTER USER SCHEMA_READER GRANT CONNECT THROUGH SYSTEM;
ALTER USER LIMITED_READER GRANT CONNECT THROUGH SYSTEM;
BEGIN
  FOR item IN (
    SELECT owner, object_name FROM dba_objects
    WHERE owner IN ('IAM','CATALOG','COMMERCE','FINANCE')
      AND object_type IN ('TABLE','VIEW')
  ) LOOP
    EXECUTE IMMEDIATE 'GRANT SELECT ON ' ||
      DBMS_ASSERT.ENQUOTE_NAME(item.owner, FALSE) || '.' ||
      DBMS_ASSERT.ENQUOTE_NAME(item.object_name, FALSE) || ' TO SCHEMA_READER';
  END LOOP;
END;
/
-- The child and view are visible, but their required definitions are not.
GRANT SELECT ON IAM.org_units TO LIMITED_READER;
GRANT SELECT ON COMMERCE.open_orders TO LIMITED_READER;

-- Cross-owner indexes: index-only owner has quota and no INDEX object grant.
CREATE USER INDEX_SCHEMA NO AUTHENTICATION DEFAULT TABLESPACE USERS QUOTA UNLIMITED ON USERS;
CREATE UNIQUE INDEX INDEX_SCHEMA.PERMISSION_KEY_IX ON IAM.PERMISSIONS(PERMISSION_ID,PERMISSION_KEY);
ALTER TABLE IAM.PERMISSIONS ADD CONSTRAINT CROSS_PERMISSION_UQ UNIQUE(PERMISSION_ID,PERMISSION_KEY) USING INDEX INDEX_SCHEMA.PERMISSION_KEY_IX;
CREATE INDEX INDEX_SCHEMA.PERMISSION_LOOKUP_IX ON IAM.PERMISSIONS(PERMISSION_KEY,PERMISSION_ID);
CREATE INDEX INDEX_SCHEMA.PERMISSION_LOWER_IX ON IAM.PERMISSIONS(LOWER(PERMISSION_KEY));

-- SQL*Plus can report package compilation errors as warnings, so fail explicitly
-- before publishing the completion marker if either specification/body is invalid.
DECLARE
  v_valid_objects NUMBER;
  v_errors NUMBER;
BEGIN
  SELECT COUNT(*) INTO v_valid_objects FROM dba_objects
    WHERE ((owner = 'COMMERCE' AND object_name = 'ORDER_MANAGEMENT')
        OR (owner = 'CATALOG' AND object_name = 'INVENTORY_MANAGEMENT'))
      AND object_type IN ('PACKAGE', 'PACKAGE BODY') AND status = 'VALID';
  SELECT COUNT(*) INTO v_errors FROM dba_errors
    WHERE ((owner = 'COMMERCE' AND name = 'ORDER_MANAGEMENT')
        OR (owner = 'CATALOG' AND name = 'INVENTORY_MANAGEMENT'))
      AND type IN ('PACKAGE', 'PACKAGE BODY') AND attribute = 'ERROR';
  IF v_valid_objects <> 4 OR v_errors <> 0 THEN
    RAISE_APPLICATION_ERROR(-20004, 'Seed packages failed compilation; inspect DBA_ERRORS.');
  END IF;
END;
/

-- This is deliberately last. Startup and health checks use it as an atomic
-- indication that all seed objects were created and the packages compiled.
CREATE SEQUENCE IAM.source_seed_complete START WITH 1 NOCACHE;

COMMIT;
PROMPT Source seed complete: IAM, CATALOG, COMMERCE, FINANCE (98 tables, 5 views, 2 packages, 2 private synonyms).
EXIT SUCCESS
